from lesson_helpers import *
from lesson_figures import figure,CSS
T=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-G21"><div class="chap"><div class="chap-head"><div class="code">G21 · Mouvements anormaux · S08 · CIM-10-GM suisse 2024</div><h1>Syndrome parkinsonien secondaire</h1><span class="status">Sol-Neurologie-G21 · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#g21-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(T,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="G21">'''
a+=sec('question','Le ralentissement est-il un diagnostic, et faut-il toujours donner de la lévodopa ?', '''<p><b>Vignette fictive.</b> Une personne traitée depuis peu pour des vomissements devient lente et raide. Une autre, sous neuroleptique, présente confusion, rigidité et température anormale. Dans un troisième dossier, un traitement antiparkinsonien a été omis pendant une hospitalisation. Les trois situations impliquent des médicaments, mais leur urgence et leur conduite ne sont pas identiques.</p><p>Il faut d’abord reconnaître le syndrome, rechercher une instabilité et reconstruire la chronologie. Une cause secondaire peut être traitable ; elle peut aussi révéler une maladie sous-jacente. Le traitement de la maladie de Parkinson n’est pas une prescription automatique pour toute personne lente.</p>'''+key('Reconnaître le syndrome, identifier le mécanisme et chercher l’urgence avant de choisir le médicament.'),('CH-HUG-SEMIO','CH-PHEL-CARE','INT-DIP-CLIN','FI-MAD'))
a+=sec(1,'1. Définition : syndrome clinique, cause et code', '''<p>Un '''+w('syndrome','syndrome parkinsonien')+''' associe une '''+w('bradykinesia','bradykinésie')+''' à une rigidité et/ou un tremblement de repos. Le tremblement n’est donc pas obligatoire. Une lenteur liée à faiblesse, douleur ou trouble cognitif ne suffit pas à conclure. La bradykinésie se caractérise par des mouvements lents, avec recherche de réduction de vitesse ou d’amplitude lors de la répétition.</p><p>Le caractère secondaire repose sur une cause identifiable et une concordance clinique. Dans la nomenclature OFS2024, G21 comprend aussi bien des formes chroniques que le <b>syndrome malin des neuroleptiques G21.0</b>. Il ne signifie pas seulement « maladie de Parkinson provoquée par un médicament ».</p>'''+table(['Sous-code OFS2024','Libellé ou portée'],[['G21.0','Syndrome malin des neuroleptiques'],['G21.1','Autres syndromes secondaires parkinsoniens dus à des médicaments'],['G21.2','Secondaire à d’autres agents externes'],['G21.3','Syndrome parkinsonien post-encéphalitique'],['G21.4','Libellé OFS : Maladie de Parkinson vasculaire'],['G21.8','Autres syndromes parkinsoniens secondaires'],['G21.9','Secondaire, sans précision']])+'''<p>Le '''+w('coding','codage')+''' distingue G20, maladie de Parkinson, G22*, syndrome au cours de maladies classées ailleurs, et G23, autres maladies dégénératives des noyaux gris. Les sous-codes.5,.6,.7 ne sont pas inventés. Pour G21.0/.1/.2, l’OFS prévoit au besoin un code supplémentaire de cause externe identifiant médicament ou agent.</p>''',('CH-CIM','CH-CIM-BOUND','EU-DGN-DEF','CH-HUG-SEMIO'))
a+=sec(2,'2. Épidémiologie : le bon sous-groupe et la bonne époque', '''<p>L’étude de Fleury et collègues, publiée en2018, décrit le canton de Genève à partir de dossiers hospitaliers, de neurologues privés et d’EMS. Elle inclut des diagnostics établis entre2003 et2012 et identifie1235 patients vivants avec parkinsonisme :80% de formes dégénératives et20% de formes non dégénératives.</p><p><b>Parmi les formes non dégénératives</b>,43,4% sont médicamenteuses et37% vasculaires dans le résumé primaire. Ces deux pourcentages ne portent ni sur toute la population genevoise ni sur l’ensemble des1235 patients. Ils ne mesurent pas une incidence nationale actuelle d’un code G21.</p><p>Le résumé, et non l’article intégral sous abonnement, a été lu. Les données sont historiques et dépendantes de la recherche des cas et de leur classification. Pour le syndrome malin, les fréquences des supports et séries varient selon période, produits et définition ; aucun chiffre unique n’est présenté comme risque individuel suisse en2026.</p>''',('CH-GENEVA','CH-PHEL-CLIN','EU-BAP-CLIN'))
a+=sec(3,'3. Physiopathologie : blocage fonctionnel, lésion et réseau', '''<p>Les noyaux gris participent à la régulation d’un '''+w('network','réseau moteur')+'''. Striatum, pallidum, noyau sous-thalamique, substance noire, thalamus et cortex ont des rôles et des connexions distincts. La '''+w('dopamine','transmission dopaminergique')+''' ne se résume pas à la force musculaire.</p>'''+figure('striatum')+'''<p>Un antagonisme '''+w('d2','D2 postsynaptique')+''' striatal peut perturber la boucle motrice sans exiger d’emblée une destruction des terminaisons présynaptiques. Ce mécanisme diffère de la perte nigrostriatale d’une maladie dégénérative, bien que celle-ci puisse être dévoilée par le médicament. Les autres médicaments ne partagent pas tous exactement le même mécanisme.</p><p>Une lésion vasculaire stratégique peut atteindre une voie ou un réseau ; une maladie diffuse des petits vaisseaux peut participer à un tableau plus complexe. Les hypersignaux ne suffisent pas, à eux seuls, à établir la causalité. Le phénotype postencéphalitique se rapporte à une affection antérieure documentée, sans présumer une inflammation encore active.</p><p>Dans le syndrome malin, le contexte dopaminergique, la thermorégulation, la rigidité et les défaillances systémiques sont discutés. La cause d’un état après '''+w('withdrawal','sevrage dopaminergique')+''' est différente d’une exposition à un antagoniste ; les consignes « arrêter » et « reprendre » ne se décident pas indistinctement.</p>''',('INT-DIP-MECH','INT-DIP-CLIN','INT-VASC-CLASS','INT-VASC-MRI','CH-PHEL-CARE','EU-BAP-CLIN','CH-CIM'))
a+=sec(4,'4. Démarche clinique : urgence, syndrome, étiologie puis plan', '''<ol><li><b>Rechercher l’urgence.</b> Confusion nouvelle, altération de conscience, température anormale, dysautonomie, rigidité importante, dégradation rapide, trouble respiratoire ou déficit brutal imposent une évaluation immédiate.</li><li><b>Objectiver le syndrome.</b> Tester gestes répétés, mobilisation passive et tremblement au repos ; distinguer faiblesse, douleur, ataxie et lenteur cognitive.</li><li><b>Reconstruire l’exposition.</b> Ordonnance complète, automédication, traitements de symptômes digestifs, injections/dépôts et médicaments récemment omis.</li><li><b>Examiner la cohérence.</b> Début, évolution, symétrie, signes non moteurs, signes pyramidaux/cérébelleux et antécédents vasculaires ou infectieux.</li><li><b>Choisir des examens et une conduite.</b> Rechercher cause et complications, adapter la stratégie avec les prescripteurs, mesurer retentissement et organiser suivi.</li></ol><p>Une '''+w('redflags','alerte clinique')+''' compte davantage qu’une étiquette ancienne. Le diagnostic d’une forme médicamenteuse n’impose pas d’attendre six mois avant d’aider le patient ; le suivi peut ensuite modifier l’hypothèse.</p>''',('CH-HUG-SEMIO','CH-HUG-DIFF','CH-PHEL-CLIN','EU-BAP-THERAPY','INT-DIP-TEST','INT-DIP-MGMT'))
a+=sec(5,'5. Anamnèse : une chronologie complète, y compris les omissions', '''<p>L’''' +w('history','histoire médicamenteuse')+''' doit reprendre noms, indications, doses, dates de début et de changement, associations, formes retard et dernière prise réelle. Demander aussi antiémétiques, prokinétiques, médicaments de vertige ou sommeil, et traitements reçus pendant une hospitalisation. Un médicament « caché » dans une autre indication peut agir sur le système dopaminergique.</p><p>La '''+w('drug-latency','relation temporelle')+''' oriente sans prouver seule la causalité. Rechercher un ralentissement antérieur, une asymétrie déjà présente, une perte d’odorat ou d’autres signes pouvant évoquer une maladie sous-jacente. Persistance ou progression après retrait peut justifier de rouvrir le diagnostic ; elle ne démontre pas immédiatement une cause unique.</p><p>Interroger marche, chutes, écriture, voix, habillage, repas et déglutition. Demander symptômes cognitifs, urinaires, autonomes et psychiatriques, en tenant compte du niveau antérieur. Une adaptation antipsychotique exige de comprendre la maladie qu’il traite et le risque de rechute.</p>''',('CH-HUG-DIFF','INT-DIP-CLIN','INT-DIP-TEST','INT-DIP-MGMT','CH-PHEL-CARE'))
a+=sec(6,'6. Examen clinique : décrire trois signes différents', '''<p>Pour la bradykinésie, observer ouverture-fermeture de main, opposition pouce-index, pronosupination et mouvements des pieds. Comparer côtés, vitesse et amplitude au fil de la répétition. Évaluer aussi lever de chaise, marche, demi-tour, ballant des bras et retentissement fonctionnel. L’''' +w('exam','examen moteur')+''' se fait avec attention à douleur, force et compréhension.</p><p>La '''+w('rigidity','rigidité extrapyramidale')+''' est une résistance au mouvement passif relativement indépendante de sa vitesse ; le patient doit être détendu. La roue dentée peut accompagner une résistance, mais un simple phénomène saccadé sans résistance ne suffit pas. Elle se distingue de l’hypertonie spastique et d’une contracture douloureuse.</p><p>Le '''+w('tremor','tremblement')+''' se décrit au repos, en posture puis en action. Un tremblement de repos et une asymétrie peuvent exister dans une forme médicamenteuse ; leur présence ne ferme pas le diagnostic. Chercher dyskinésies bucco-linguo-faciales, signes pyramidaux, coordination, oculomotricité, cognition et autonomie.</p>'''+figure('posture')+'''<p>Le dessin montre une attitude, pas une preuve de rigidité ni une mesure de bradykinésie. Chez un patient fébrile ou confus, le bilan neurologique s’intègre au triage et au bilan des complications.</p>''',('CH-HUG-SEMIO','CH-HUG-DIFF','EU-DGN-DEF','INT-DIP-CLIN','CH-PHEL-CLIN','IMG-GOWERS'))
a+=sec(7,'7. Syndromes : un regroupement qui guide la question',table(['Profil','Hypothèses et limites'],[['Parkinsonisme sous médicament','Chronologie et exposition ; retrait/substitution à discuter, maladie dégénérative concomitante possible'],['Prédominance marche/axe avec signes associés','Cause vasculaire, hydrocéphalie, myélopathie ou autre réseau ; IRM à relier au tableau'],['Rigidité avec confusion, température/dysautonomie','Syndrome malin, catatonie maligne, sérotoninergique, infection ou autre défaillance urgente'],['Après encéphalite documentée','Déficit résiduel, complication ou nouvelle activité à distinguer ; G21.3 seulement si tableau approprié'],['Après omission d’un antiparkinsonien','État de sevrage possible, pouvant ressembler à SMN ; étiologie et prise en charge urgentes propres']])+figure('motor')+'''<p>Une '''+w('iatrogenic','cause iatrogène')+''' peut produire plusieurs mouvements anormaux. Parkinsonisme, akathisie, dystonie aiguë et dyskinésie tardive ne sont pas des synonymes ; une même personne peut présenter plusieurs dimensions. Les traitements de l’une peuvent aggraver l’autre.</p>''',('CH-CIM','INT-DIP-CLIN','INT-DIP-MECH','INT-VASC-CLASS','INT-VASC-MRI','EU-BAP-CLIN','FI-AKI','FI-MAD'))
a+=sec(8,'8. Diagnostic positif : ce qui est établi et ce qui reste probable', '''<p><b>Le syndrome est clinique.</b> Objectiver bradykinésie et rigidité et/ou tremblement de repos, puis décrire retentissement. Les critères de maladie de Parkinson idiopathique et ceux d’une cause secondaire ne sont pas identiques. Une réponse à un traitement n’établit pas à elle seule toute l’étiologie.</p><p><b>Origine médicamenteuse.</b> L’exposition connue, l’absence de syndrome avant traitement et le début sous le médicament soutiennent l’hypothèse. L’amélioration après réduction ou retrait est utile, mais le suivi peut révéler une coexistence ou une maladie dévoilée. Ni symétrie obligatoire ni guérison complète à une date fixe ne doivent être exigées.</p><p><b>Origine '''+w('vascular','vasculaire')+'''.</b> Rechercher concordance entre début, profil clinique et lésions pertinentes. Distinguer forme postAVC, forme insidieuse et forme mixte ; des hypersignaux de substance blanche isolés ne suffisent pas.</p><p><b>Contexte '''+w('postenceph','postencéphalitique')+'''.</b> Documenter l’affection et la trajectoire, sans conclure automatiquement à une activité immunitaire persistante. Le code est choisi après caractérisation, en tenant compte des catégories distinctes.</p>''',('EU-DGN-DEF','INT-DIP-TEST','INT-DIP-MGMT','INT-VASC-CLASS','INT-VASC-MRI','CH-CIM','CH-CIM-BOUND'))
a+=sec(9,'9. Explorations : une cible clinique pour chaque examen', '''<p>La biologie recherche complications et autres causes, notamment si syndrome malin suspecté : '''+w('ck','CK et rhabdomyolyse')+''', fonction rénale, potassium et autres ions, paramètres de perfusion, bilan hépatique et explorations infectieuses selon tableau. Un résultat isolé ne confirme ni n’exclut un syndrome malin ; les intervalles du laboratoire suisse et les unités doivent être vérifiés.</p><p>L’''' +w('mri','IRM cérébrale')+''' est utile au diagnostic différentiel d’un syndrome parkinsonien, avec question structurale et vasculaire. Une image ne mesure pas seule le retentissement ni la causalité. Une urgence vasculaire ou infectieuse suit son propre circuit.</p><p>Le '''+w('dat','DAT-SPECT')+''' évalue des terminaisons présynaptiques nigrostriatales. Il peut aider dans un syndrome cliniquement incertain si le résultat change la conduite. Un déficit n’identifie pas seul une maladie de Parkinson idiopathique ; une préservation peut soutenir une perturbation surtout postsynaptique. L’équipe de médecine nucléaire vérifie préparation, traitements interférents et indication.</p>''',('CH-PHEL-CLIN','EU-BAP-THERAPY','EU-DGN-IMG','INT-DIP-TEST','INT-VASC-MRI'))
a+=sec(10,'10. Arbre diagnostique et diagnostics différentiels', '''<ol><li><b>Instabilité ou apparition brutale ?</b> Évaluer immédiatement urgence systémique, vasculaire, infectieuse ou toxique.</li><li><b>Syndrome parkinsonien objectivé ?</b> Séparer bradykinésie, rigidité, tremblement, faiblesse et trouble de coordination.</li><li><b>Exposition ou omission pertinente ?</b> Reconstituer chronologie et bénéfice/risque de l’ordonnance.</li><li><b>Indices d’autre cause ou de coexistence ?</b> Début antérieur, progression, signes non moteurs, tableau atypique, lésions concordantes.</li><li><b>Conclusion proportionnée ?</b> Hypothèse, examens utiles, plan thérapeutique et suivi mesurable, avec codage approprié.</li></ol><p>Parmi les urgences, différencier '''+w('nms','syndrome malin des neuroleptiques')+''', '''+w('catatonia','catatonie maligne')+''' et '''+w('serotonin','toxicité sérotoninergique')+''' peut être difficile. Le médicament, la chronologie et tout l’examen comptent ; un signe ou un dosage ne remplace pas l’enquête. Une infection du SNC ou un sepsis ne doivent pas être exclus par l’existence d’un neuroleptique dans le dossier.</p><p>Hors urgence, considérer maladie de Parkinson, autres maladies dégénératives, hydrocéphalie, trouble de marche frontal ou médullaire et maladies classées ailleurs. G21 n’est pas une catégorie qui absorbe tous ces diagnostics.</p>''',('CH-HUG-DIFF','EU-BAP-CLIN','CH-PHEL-CLIN','INT-VASC-MRI','CH-CIM-BOUND','INT-DIP-CLIN'))
a+=sec(11,'11. Prise en charge : la cause avant la surenchère symptomatique', '''<p><b>Parkinsonisme médicamenteux sans urgence.</b> '''+w('reduce','Réévaluer le médicament causal')+''' : indication, dose minimale utile, réduction, retrait ou substitution coordonnés avec le prescripteur, particulièrement en psychiatrie. L’objectif inclut contrôle de la maladie traitée et fonction du patient ; il ne s’agit pas d’arrêter tous les traitements sans plan.</p><p>Un traitement symptomatique peut être discuté chez certains patients gênés. Les FI d’''' +w('akineton','Akineton')+''' et de '''+w('amantadine','Symmetrel')+''' précisent indications et risques ; l’autorisation ne signifie pas une preuve forte de bénéfice chez tous. Confusion, psychose, rétention urinaire, chutes et fonction rénale peuvent modifier le choix. '''+w('levodopa','Madopar')+''' exclut le syndrome d’origine médicamenteuse dans sa FI suisse.</p><p><b>Syndrome malin suspecté.</b> Prise en charge urgente, arrêt des antagonistes dopaminergiques et des anticholinergiques selon BAP, soutien des fonctions vitales et surveillance des complications. Les options spécialisées, dont '''+w('bromocriptine','bromocriptine')+''', dépendent de gravité et de contexte, avec preuves limitées. Le schéma de Parkinson d’une FI ne devient pas une dose autorisée de SMN. Un état après sevrage dopaminergique pose une conduite spécifique de reprise évaluée.</p><p><b>Autres causes.</b> Cause vasculaire, toxique ou postencéphalitique : traiter la maladie identifiée et organiser l’avis adapté. Un essai dopaminergique peut être pertinent dans certains profils, sans bénéfice universel. Un antithrombotique ou une immunothérapie ne se déduit pas du seul code.</p><p><b>Fonction.</b> '''+w('rehab','Rééducation et adaptations')+''' selon marche, équilibre, activités, parole et déglutition ; prévenir chutes et aspiration et soutenir l’entourage. Évaluer le résultat sur des objectifs concrets.</p>''',('INT-DIP-MGMT','INT-DIP-LIMIT','FI-AKI','FI-SYM','FI-MAD','FI-PARL','EU-BAP-THERAPY','EU-BAP-LIMIT','CH-PHEL-CARE','INT-VASC-RESPONSE','CH-HUG-DIFF'))
a+=sec(12,'12. Prévention, suivi et pronostic : vérifier la trajectoire', '''<p>Le '''+w('follow','suivi')+''' compare signes et fonction après toute adaptation : gestes utiles, marche, chutes, cognition, symptômes psychiatriques et tolérance. Une amélioration peut prendre des semaines ou mois ; persistance, progression ou réapparition réclame une nouvelle évaluation. Une récupération complète n’est pas garantie par la seule étiquette médicamenteuse.</p><p>Après syndrome malin, la reprise d’un antipsychotique se décide avec les équipes compétentes. BAP2023 recommande d’attendre <b>au moins deux semaines après résolution</b>, puis faible dose, progression prudente et surveillance ; le support PHEL propose une fenêtre5–14jours. Ces références ne deviennent pas un délai moyen ou un automatisme de reprise.</p><p>La '''+w('prevention','prévention')+''' repose notamment sur indications médicamenteuses pertinentes, réévaluation des associations et repérage de nouveaux mouvements anormaux. Maintenir une transmission fiable des antiparkinsoniens lors des transitions de soins, avec une solution adaptée si déglutition impossible.</p><p>Les '''+w('elderly','personnes âgées')+''', les patients avec atteinte '''+w('renal','rénale')+''' et les situations de '''+w('pregnancy','grossesse/allaitement')+''' demandent une vérification propre au produit. Les formes et les bornes d’âge ne sont pas interchangeables entre médicaments.</p>''',('INT-DIP-MGMT','INT-DIP-LIMIT','EU-BAP-RECHALL','CH-PHEL-RECHALL','FI-SYM','FI-AKI','FI-MAD','FI-PARL'))
a+=sec(13,'13. Points clés : une décision qui reste vérifiable', '''<ul><li>Le syndrome n’est pas synonyme de maladie de Parkinson idiopathique.</li><li>Bradykinésie, rigidité et tremblement demandent des tests différents ; tremblement et symétrie ne sont pas obligatoires.</li><li>G21 comprend le syndrome malin aigu et des causes chroniques distinctes.</li><li>Lire toute l’ordonnance et les omissions ; une cause médicamenteuse peut dévoiler une autre maladie.</li><li>Une IRM vasculaire ou un DAT anormal ne fournit pas seul toute l’étiologie.</li><li>Le traitement est causal, fonctionnel et individualisé ; la FI de Madopar exclut le parkinsonisme médicamenteux.</li><li>Une rigidité fébrile/confuse ne se traite pas par bipéridène automatique ; arrêter les anticholinergiques fait partie des recommandations SMN BAP.</li><li>Vérifier produit, âge, organes, dose par prise et intervalle.</li></ul>''',('CH-CIM','CH-CIM-BOUND','EU-DGN-DEF','INT-DIP-CLIN','INT-DIP-TEST','FI-MAD','EU-BAP-THERAPY','FI-SYM'))
a+=sec(14,'14. Pièges : ne pas faire d’une ressemblance une équivalence', '''<p>Confondre lenteur et bradykinésie, posture et rigidité, symptôme médicamenteux et maladie dégénérative, ou image vasculaire et cause prouvée sont des raccourcis différents. La photo histologique d’un pigment ne mesure pas un récepteur dopaminergique et un dessin historique n’est pas un cas secondaire diagnostiqué.</p><p>Les erreurs de prescription comprennent donner100mg d’amantadine deuxfois/j à une personne âgée sans réévaluer son âge et son rein, assimiler125mg de Madopar à125mg de lévodopa, casser une forme retard non divisible ou appliquer une dose Parkinson à un SMN. La fenêtre '''+w('calculation','calcul et formulation')+''' explique les unités utiles.</p><p>Enfin, « arrêter le médicament causal » n’est pas une consigne identique dans le blocage dopaminergique et dans l’omission d’un traitement dopaminergique. L’urgence et l’indication guident les actions. Les cas et quiz sont fictifs et originaux, sans statut de questions fédérales officielles.</p>'''+trap('Toujours relier population, cause, produit, formulation et chronologie avant de conclure.'),('INT-DIP-CLIN','INT-VASC-MRI','FI-SYM','FI-MAD','FI-AKI','CH-PHEL-CARE','CH-PROFILES','CH-MEBEKO','IMG-HISTO','IMG-GOWERS'))
a+='</div></div>';save('a',a)
print('G21 : quatorze points monographiques écrits avec causes et populations distinctes.')
